mapper.select:
SELECT
FINPROD_ID id,
FINPROD_NAME text,
PROFIT_TYPE object
FROM
FIN_PRODUCT
WHERE P_FINPROD_ID IS NULL
AND DATE_FORMAT(MDATE,'%Y-%m-%d') > #{vdate}

AND DATE_FORMAT(MDATE,'%Y-%m-%d') > #{mdate}

AND PROFIT_TYPE <> #{profitType}


AND DATE_FORMAT(VDATE,'%Y-%m-%d') <= #{vdate}

    AND FINPROD_NAME like concat_ws('', '%', #{search,jdbcType=VARCHAR}, '%')
